// Простой keyword-routing для делегирования агенту.
// Если есть ANTHROPIC_API_KEY — будем дергать Claude отдельным узлом ниже.
const body = $input.item.json.body || $input.item.json;
const message = (body.message || '').toLowerCase();
const history = body.history || [];
const kbContext = body.kbContext || [];

function route(msg) {
  if (/(контент.?план|план.{0,10}пост|идеи)/.test(msg)) return 'marketer';
  if (/(напиши пост|напиши текст|текст поста)/.test(msg)) return 'copywriter';
  if (/(обложк|визуал|картинк|дизайн)/.test(msg)) return 'designer';
  if (/(ресёрч|ресерч|конкурент|спарси|тренд|инсайт)/.test(msg)) return 'researcher';
  if (/(аналитик|метрик|охват|er|отчёт|статистик)/.test(msg)) return 'analyst';
  return 'mary';
}

const agent = route(message);
const replies = {
  marketer:   'Передаю Маркетологу — соберёт идеи постов под твой бриф.',
  copywriter: 'Передаю Копирайтеру — напишет драфт в твоём ToV.',
  designer:   'Передаю Дизайнеру — даст 3 варианта обложки.',
  researcher: 'Ресерчер уже на ходу — собирает свежие посты.',
  analyst:    'Спрошу Аналитика — он принесёт цифры по последним постам.',
  mary:       'Понял. Опиши задачу подробнее — я передам нужному агенту или сделаю сама.',
};

return {
  json: {
    agentId: 'mary',
    text: replies[agent],
    delegateTo: agent === 'mary' ? null : agent,
    timestamp: new Date().toISOString(),
    backend: 'n8n-mock',
  },
};
